def employee_free_time(schedule):
    all_intervals = [iv for emp in schedule for iv in emp]
    all_intervals.sort(key=lambda x: x[0])                 # sort the flattened list
    merged = []
    for start, end in all_intervals:
        if merged and start <= merged[-1][1]:
            merged[-1][1] = max(merged[-1][1], end)              # extend, standard Merge Intervals
        else:
            merged.append([start, end])
    result = []
    for i in range(1, len(merged)):
        result.append([merged[i - 1][1], merged[i][0]])           # gap between consecutive merged intervals
    return result

