import java.util.*;

public class Main {
    static List<int[]> employeeFreeTime(List<List<int[]>> schedule) {
        List<int[]> all = new ArrayList<>();
        for (List<int[]> emp : schedule) all.addAll(emp);
        all.sort((a, b) -> a[0] - b[0]);                           // sort the flattened list
        List<int[]> merged = new ArrayList<>();
        for (int[] iv : all) {
            if (!merged.isEmpty() && iv[0] <= merged.get(merged.size() - 1)[1]) {
                merged.get(merged.size() - 1)[1] = Math.max(merged.get(merged.size() - 1)[1], iv[1]);  // extend
            } else {
                merged.add(iv);
            }
        }
        List<int[]> result = new ArrayList<>();
        for (int i = 1; i < merged.size(); i++) {
            result.add(new int[]{merged.get(i - 1)[1], merged.get(i)[0]});      // gap between merged intervals
        }
        return result;
    }
}

