#include <bits/stdc++.h>
using namespace std;

vector<vector<int>> employeeFreeTime(vector<vector<vector<int>>>& schedule) {
    vector<vector<int>> all;
    for (auto& emp : schedule) for (auto& iv : emp) all.push_back(iv);
    sort(all.begin(), all.end());                                  // sort the flattened list
    vector<vector<int>> merged;
    for (auto& iv : all) {
        if (!merged.empty() && iv[0] <= merged.back()[1]) {
            merged.back()[1] = max(merged.back()[1], iv[1]);          // extend, standard Merge Intervals
        } else {
            merged.push_back(iv);
        }
    }
    vector<vector<int>> result;
    for (int i = 1; i < (int)merged.size(); i++) {
        result.push_back({merged[i-1][1], merged[i][0]});             // gap between merged intervals
    }
    return result;
}
